  "Product cost is snapshotted at checkout. Later cost changes do not rewrite completed sales. Older sales without cost snapshots may show zero cost and are counted as uncosted.": {
    "es": "El costo se registra al cobrar. Los cambios posteriores no reescriben ventas completas. Ventas antiguas sin costo guardado pueden mostrar cero y se cuentan sin costo.",
    "zh-TW": "商品成本會在結帳時建立快照。後續成本變更不會改寫已完成銷售。缺少成本快照的舊銷售可能顯示零成本，並計為未計成本。",
    "zh-CN": "商品成本会在结账时创建快照。后续成本更改不会改写已完成销售。缺少成本快照的旧销售可能显示零成本，并计为未计成本。"
  },
  "Production approval is immutable evidence. Later corrections create a new review; they do not edit or delete the prior approval.": {
    "es": "La aprobación de producción es evidencia inmutable. Las correcciones crean otra revisión, sin editar ni eliminar la aprobación anterior.",
    "zh-TW": "生產核准為不可變更的證明。後續修正會建立新審核，不會編輯或刪除先前核准。",
    "zh-CN": "生产批准为不可更改的证明。后续修正会创建新审核，不会编辑或删除先前批准。"
  },
  "Production automatically consumes the earliest usable expiry first. Expired and recalled lots are blocked from production.": {
    "es": "La producción consume primero el vencimiento utilizable más próximo. Los lotes vencidos o retirados quedan bloqueados.",
    "zh-TW": "生產會優先耗用最早到期的可用原料。過期與召回批次不得投入生產。",
    "zh-CN": "生产会优先消耗最早到期的可用原料。过期与召回批次不得投入生产。"
  },
