  "Refunds and voids require a manager PIN and are saved to the audit trail. Card/QR payment reversals must also be completed with the external payment terminal/provider until payment processing is integrated.": {
    "es": "Reembolsos y anulaciones requieren PIN gerencial y se auditan. Hasta integrar pagos, también deben revertirse los pagos de tarjeta/QR con el proveedor externo.",
    "zh-TW": "退款與作廢需要經理 PIN，並保存於稽核紀錄。整合付款處理前，信用卡／QR 付款也必須在外部付款終端機／服務商處撤銷。",
    "zh-CN": "退款与作废需要经理 PIN，并保存于审计记录。集成支付处理前，银行卡／二维码支付也必须在外部支付终端机／服务商处撤销。"
  },
  "Refunds and voids require an active Admin's approval PIN. The PIN is stored as a secure hash in Supabase and is never shown again.": {
    "es": "Reembolsos y anulaciones requieren PIN de un administrador activo. El PIN se guarda como hash seguro en Supabase y no vuelve a mostrarse.",
    "zh-TW": "退款與作廢需要在職管理員核准 PIN。PIN 以安全雜湊儲存於 Supabase，不會再次顯示。",
    "zh-CN": "退款与作废需要在职管理员批准 PIN。PIN 以安全哈希保存于 Supabase，不会再次显示。"
  },
  "Regular price is the master product price. Current catalogue prices include active variant pricing and promotions; checkout verifies the same server prices. Base margin uses regular price; final margins are in Profitability.": {
    "es": "El precio habitual es el maestro. El catálogo incluye variantes y promociones activas; caja verifica los mismos precios del servidor. El margen base usa precio habitual; los finales están en Rentabilidad.",
    "zh-TW": "原價為商品主檔價格。目前目錄價格包含有效規格價格與促銷；結帳會驗證相同的伺服器價格。基礎毛利使用原價，最終毛利請見獲利分析。",
    "zh-CN": "原价为商品主档价格。当前目录价格包含有效规格价格与促销；结账会验证相同的服务器价格。基础毛利使用原价，最终毛利请见获利分析。"
  },
