  "Use the form when an operational problem needs management follow-up.": {
    "es": "Use el formulario si un problema operativo requiere seguimiento gerencial.",
    "zh-TW": "作業問題需要管理人員跟進時，請使用表單。",
    "zh-CN": "作业问题需要管理人员跟进时，请使用表单。"
  },
  "Use this HTTPS address on authorized devices. Keep customer share links private and rotate them in Customer View Setup when necessary.": {
    "es": "Use esta dirección HTTPS en dispositivos autorizados. Mantenga privados los enlaces de clientes y renueve en Configuración de vista del cliente.",
    "zh-TW": "請在授權裝置使用此 HTTPS 網址。保持顧客分享連結私密，必要時在顧客顯示設定中輪替。",
    "zh-CN": "请在授权设备使用此 HTTPS 网址。保持顾客分享链接私密，必要时在顾客显示设置中更换。"
  },
  "Use This Logo": {
    "es": "Usar este logotipo",
    "zh-TW": "使用此標誌",
    "zh-CN": "使用此标志"
  },
  "Use this only when Supabase email delivery is configured. It uses the name, email, and role entered above.": {
    "es": "Use solo con envío de correo Supabase configurado. Usa el nombre, correo y rol de arriba.",
    "zh-TW": "僅在已設定 Supabase 電子郵件傳送時使用。此功能使用上方輸入的姓名、電子郵件與角色。",
    "zh-CN": "仅在已配置 Supabase 电子邮件发送时使用。此功能使用上方输入的姓名、电子邮件与角色。"
  },
  "Use Trace to identify every production batch that consumed a selected lot.": {
    "es": "Use Trazabilidad para identificar cada lote de producción que consumió el lote elegido.",
    "zh-TW": "使用追溯以識別耗用所選原料批次的每個生產批次。",
    "zh-CN": "使用追溯以识别消耗所选原料批次的每个生产批次。"
  },
  "Use Void for a completed sale entered by mistake. All sale quantities are returned to inventory and loyalty activity is reversed.": {
    "es": "Use Anular para ventas completas erróneas. Las cantidades vuelven al inventario y se revierte la fidelidad.",
    "zh-TW": "誤登已完成銷售請使用作廢。所有銷售數量將退回庫存，會員活動也會撤銷。",
    "zh-CN": "误登已完成销售请使用作废。所有销售数量将退回库存，会员活动也会撤销。"
  },
