    "zh-TW": "警報連結至原始紀錄，不會變更任務、事件、檢查清單、銷售或每日現金。確認及解決操作會追加不可變更的事件。",
    "zh-CN": "警报关联至原始记录，不会更改任务、事件、检查清单、销售或每日现金。确认及解决操作会追加不可变更的事件。"
