    "es": "días válidos. Sugerido = máx(redondear hacia arriba(promedio × margen + pedidos para retirar − inventario actual − producción planificada), 0). Las cantidades son unidades base de receta e incluyen escalas por variante. Las previsiones nunca consumen inventario.",
