    "zh-CN": "个符合条件的日期。建议量 = 最大值（向上取整（平均 × 缓冲 + 取货订单 − 当前库存 − 计划产量），0）。数量以基本配方单位计算，包含规格的配方比例。预测不会消耗库存。"
