  "Expected costs form the delivery-variance baseline.": {
    "es": "Los costos previstos son la base de comparación de variaciones en entrega.",
    "zh-TW": "預期成本為到貨差異比較基準。",
    "zh-CN": "预期成本为到货差异比较基准。"
  },
  "Expected quantity and cost form the receiving baseline.": {
    "es": "La cantidad y el costo previstos forman la base de recepción.",
    "zh-TW": "預期數量與成本為收貨基準。",
    "zh-CN": "预期数量与成本为收货基准。"
  },
  "Expenses are append-only. Cash expenses automatically create an audited cash-out entry when a drawer is open; card and bank expenses do not affect drawer cash.": {
    "es": "Los gastos solo se agregan. Los gastos en efectivo crean automáticamente una salida auditada si hay un cajón abierto; los pagos con tarjeta o banco no afectan su efectivo.",
    "zh-TW": "支出僅能追加。錢櫃開啟時，現金支出會自動建立經稽核的現金支出紀錄；刷卡及銀行支出不影響錢櫃現金。",
    "zh-CN": "支出仅能追加。钱箱开启时，现金支出会自动创建经审计的现金支出记录；刷卡及银行支出不影响钱箱现金。"
  },
  "Expired or recalled finished products require management review. Use Trace before disposal so affected receipts remain documented.": {
    "es": "Los productos terminados vencidos o retirados requieren revisión gerencial. Use Trazabilidad antes de eliminarlos para conservar los recibos afectados.",
    "zh-TW": "過期或召回成品須由管理人員審查。報廢前請先使用追溯功能，以保留受影響收據紀錄。",
    "zh-CN": "过期或召回成品须由管理人员审查。报废前请先使用追溯功能，以保留受影响收据记录。"
  },
  "Expired or recalled ingredient stock remains on hand. Review the highlighted lots and record a controlled disposal.": {
    "es": "Los ingredientes vencidos o retirados permanecen en existencia. Revise los lotes resaltados y registre una eliminación controlada.",
    "zh-TW": "過期或召回原料仍計入現有庫存。請審查標示批次，並記錄受控報廢。",
    "zh-CN": "过期或召回原料仍计入现有库存。请审查标示批次，并记录受控报废。"
  },
