  "For a possible duplicate payment, missing paid sale, or wrong-business data, stop the affected workflow and contact the manager immediately.": {
    "es": "Ante un posible pago duplicado, una venta pagada que falta o datos de otro negocio, detenga el flujo afectado y contacte inmediatamente al gerente.",
    "zh-TW": "若可能重複付款、已付款銷售遺失或出現其他商家資料，請停止相關流程並立即聯絡主管。",
    "zh-CN": "若可能重复付款、已付款销售丢失或出现其他商家资料，请停止相关流程并立即联系主管。"
  },
  "For production use, a 6-digit or longer PIN is recommended. Each refund or void records both the staff member who processed it and the manager who approved it.": {
    "es": "Para producción se recomienda un PIN de 6 dígitos o más. Cada reembolso o anulación registra al empleado que lo procesó y al gerente que lo autorizó.",
    "zh-TW": "正式使用建議採用至少 6 位數 PIN。每筆退款或作廢都會記錄處理員工及核准主管。",
    "zh-CN": "正式使用建议采用至少 6 位数 PIN。每笔退款或作废都会记录处理员工及批准主管。"
  },
  "For safety, v6 does not queue offline sales. Inventory, loyalty balances, refunds and new sales remain server-authoritative and require a connection.": {
    "es": "Por seguridad, v6 no pone ventas sin conexión en cola. El inventario, saldos de lealtad, reembolsos y nuevas ventas siguen bajo autoridad del servidor y requieren conexión.",
    "zh-TW": "基於安全考量，v6 不會將離線銷售排入佇列。庫存、會員餘額、退款及新銷售仍以伺服器為準，並需要連線。",
    "zh-CN": "基于安全考虑，v6 不会将离线销售排入队列。库存、会员余额、退款及新销售仍以服务器为准，并需要连接。"
  },
