  "Guest transactions have no contact details. Use the receipt number and timestamp for internal investigation; do not treat a missing customer record as proof the unit was not sold.": {
    "es": "Las transacciones de invitados no tienen contacto. Use el número de recibo y la hora para investigar internamente; la ausencia de cliente no demuestra que no se vendió la unidad.",
    "zh-TW": "訪客交易沒有聯絡資料。請使用收據編號及時間戳記進行內部調查；沒有顧客紀錄並不代表該單位未售出。",
    "zh-CN": "访客交易没有联系资料。请使用收据编号及时间戳进行内部调查；没有顾客记录并不代表该单位未售出。"
  },
  "Handover could not be created.": {
    "es": "No se pudo crear la entrega de turno.",
    "zh-TW": "無法建立交班。",
    "zh-CN": "无法创建交班。"
  },
  "Hardware settings stay on this device and contain no Supabase credentials. System Print remains available if a direct connection fails.": {
    "es": "La configuración de hardware permanece en este dispositivo y no contiene credenciales Supabase. Impresión del sistema sigue disponible si falla la conexión directa.",
    "zh-TW": "硬體設定保留於此裝置，不含 Supabase 憑證。直接連線失敗時仍可使用系統列印。",
    "zh-CN": "硬件设置保留于此设备，不含 Supabase 凭证。直接连接失败时仍可使用系统打印。"
  },
  "Healthy operation still requires routine backup, Daily Cash, and recall reviews.": {
    "es": "Una operación sana aún requiere respaldos rutinarios y revisiones de Caja diaria y retiros.",
    "zh-TW": "正常營運仍須定期備份，並審查每日現金與召回。",
    "zh-CN": "正常运营仍须定期备份，并审查每日现金与召回。"
  },
